const expectedIds=[...Array.from({length:30},(_,i)=>'P1-02/F'+String(i+1).padStart(2,'0')),...Array.from({length:40},(_,i)=>'P1-03/A'+String(i+1).padStart(2,'0')),...Array.from({length:20},(_,i)=>'P1-02/R'+String(i+1).padStart(2,'0')),...Array.from({length:22},(_,i)=>'P1-04/B'+String(i+1).padStart(2,'0'))];
