  fs.writeFileSync(path.join(out,'acceptance-results.json'),JSON.stringify({...auto,status:'incomplete'},null,2));
  const manual=JSON.parse(fs.readFileSync(path.join(out,'manual-review.json')));
  const actual=auto.results.map(r=>r.id),reviews=manual.reviews;
  const complete=auto.runId===manual.runId && JSON.stringify(auto.implementationHashes)===JSON.stringify(implementationHashes()) && JSON.stringify(auto.sourceHashes)===JSON.stringify(hashes()) && actual.length===112 && new Set(actual).size===112 && expectedIds.every(id=>actual.includes(id)) && auto.results.every(r=>r.status==='passed'||(r.status==='pending-manual'&&manualIds.includes(r.id.split('/')[1]))) && manualIds.every(id=>reviews.some(r=>r.id==='P1-04/'+id && r.status==='passed' && r.observed && r.evidence.length && r.evidence.every(f=>fs.existsSync(path.join(root,f))))) && auto.consoleErrors.length===0;
