const chooseDate=async date=>{
  await tab('diary');
  while((await p.locator('#calendar [data-date]').first().getAttribute('data-date')).slice(0,7)!==date.slice(0,7)){
    const current=(await p.locator('#calendar [data-date]').first().getAttribute('data-date')).slice(0,7);
    await p.locator(current>date.slice(0,7)?'#previous-month':'#next-month').click();
  }
  await p.locator(`[data-date="${date}"]`).click();
};
