const bounds=async selectors=>{const bad=await p.locator(selectors).evaluateAll(es=>es.filter(e=>e.getBoundingClientRect().width>0).map(e=>({text:e.textContent.slice(0,50),width:e.getBoundingClientRect().width,height:e.getBoundingClientRect().height})).filter(e=>e.width<43.9||e.height<43.9));assert.deepEqual(bad,[]);};
